from datetime import datetime, timezone

# service (lowercase) -> (max attempts, backoff cap, longest accepted Retry-After)
_PROFILES = {
    "payments": (3, 1, 30),
    "ledger-export": (4, 8, 10),
    "reports": (9, 5, 120),
    "inventory": (7, 4, 90),
    "search": (10, 12, 45),
    "shipping": (8, 3, 40),
    "media": (5, 8, 15),
    "catalog": (6, 8, 30),
    "auth": (6, 6, 20),
    "ledger": (8, 3, 60),
}
_IDEMPOTENT = {"GET", "HEAD", "OPTIONS", "PUT", "DELETE"}
_DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
_MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun",
           "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
_DATE_RE = re.compile(
    r"([A-Z][a-z]{2}), (\\d{2}) ([A-Z][a-z]{2}) (\\d{4}) (\\d{2}):(\\d{2}):(\\d{2}) GMT"
)


def _get(headers, name):
    for k, v in (headers or {}).items():
        if k.lower() == name:
            return v
    return None


def _retry_after(value, now):
    """Seconds, or None if absent/malformed."""
    if value is None:
        return None
    value = value.strip()
    if re.fullmatch(r"[0-9]+", value):
        return float(int(value))
    m = _DATE_RE.fullmatch(value)
    if not m or m[1] not in _DAYS or m[3] not in _MONTHS:
        return None
    try:
        dt = datetime(int(m[4]), _MONTHS.index(m[3]) + 1, int(m[2]),
                      int(m[5]), int(m[6]), int(m[7]), tzinfo=timezone.utc)
    except ValueError:
        return None
    if _DAYS[dt.weekday()] != m[1]:
        return None
    return max(0.0, (dt - now).total_seconds())
''')
